namespace Hugo.Core.Agent
{
    using System;
    using Hugo.Core.Inference;

    /// <summary>
    /// Everything one turn needs. The surface (chat route, A2A, OpenAI-compatible, <c>ask_agent_smith</c>) builds
    /// it after authentication and profile resolution. Not thread-safe; build one per turn.
    /// </summary>
    public class AgentTurnRequest
    {
        #region Public-Members

        /// <summary>
        /// Turn ID. Generated by the runtime when empty.
        /// </summary>
        public string TurnId
        {
            get
            {
                return _TurnId;
            }
            set
            {
                _TurnId = value ?? String.Empty;
            }
        }

        /// <summary>
        /// Tenant ID.
        /// </summary>
        public string TenantId { get; set; } = String.Empty;

        /// <summary>
        /// Conversation ID. Required.
        /// </summary>
        public string ConversationId { get; set; } = String.Empty;

        /// <summary>
        /// Principal (user or credential) ID.
        /// </summary>
        public string? PrincipalId { get; set; } = null;

        /// <summary>
        /// Agent profile ID.
        /// </summary>
        public string? ProfileId { get; set; } = null;

        /// <summary>
        /// Surface label for metrics and events: <c>chat</c>, <c>a2a</c>, <c>openai</c>, <c>mcp</c>. Default <c>chat</c>.
        /// </summary>
        public string Surface { get; set; } = "chat";

        /// <summary>
        /// Compiled instructions (persona plus service sections) used as the system prompt. Required.
        /// </summary>
        public string SystemPrompt { get; set; } = String.Empty;

        /// <summary>
        /// The user's message. Required.
        /// </summary>
        public string UserMessage { get; set; } = String.Empty;

        /// <summary>
        /// Profile inference endpoint. Required.
        /// </summary>
        public ModelEndpointConfig? InferenceEndpoint { get; set; } = null;

        /// <summary>
        /// Profile fallback inference endpoint. Optional.
        /// </summary>
        public ModelEndpointConfig? FallbackEndpoint { get; set; } = null;

        /// <summary>
        /// Profile embedding endpoint, used for tool retrieval. Optional.
        /// </summary>
        public ModelEndpointConfig? EmbeddingEndpoint { get; set; } = null;

        /// <summary>
        /// Tool catalog for this turn. Null offers no tools.
        /// </summary>
        public IAgentToolCatalog? ToolCatalog { get; set; } = null;

        /// <summary>
        /// Tool executor for this turn. Required when a catalog is set.
        /// </summary>
        public IAgentToolExecutor? ToolExecutor { get; set; } = null;

        /// <summary>
        /// Event sink. Null discards events.
        /// </summary>
        public IAgentEventSink? EventSink { get; set; } = null;

        /// <summary>
        /// Settings for this turn (for example profile overrides). Null uses the runtime's settings.
        /// </summary>
        public AgentRuntimeSettings? Settings { get; set; } = null;

        #endregion

        #region Private-Members

        private string _TurnId = String.Empty;

        #endregion
    }
}
